changeSet.sql:
create or alter procedure api.UpsertChangeLog @executionId int, @object varchar(50) as begin set nocount on; declare @userId int, @date datetime;
select @userId = ResourceID, @date = StartedOn from api.Execution where ID = @executionId;
drop table if exists #Assets; create table #Assets ([Uid] uniqueidentifier, ObjectID int, AssetID bigint);
-- Get data from JSON columns in api.ExecutionItem insert into #Assets (Uid, ObjectID, AssetID) select Uid, ObjectID, AssetID from #Items where IsValid is null;
declare @tbl table (ID bigint, Object varchar(50), ObjectID int) insert into reporting.Global_Audit (Object, ObjectID, ObjectName, ResourceID, Date, [Version], Action, ActionObject, ActionObjectID, ActionObjectTypeName, ActionObjectName, ActionDescription) output inserted.ID, inserted.Object, inserted.ObjectID into @tbl select a.Object, a.ObjectId, d.DisplayValue, @userId, @date, mv.[Version], iif(mv.[Version] = 1, 'Created', 'Updated'), a.Object, a.ObjectId, t.Name, d.DisplayValue, 'This has been ' + iif(mv.[Version] = 1, 'created', 'updated') + '.' from #Assets l inner join Asset a on a.Id = l.AssetID inner join AssetDisplayValue d on d.AssetID = a.Id inner join AssetType t on t.Id = a.AssetTypeId cross apply (select coalesce(max([Version]),0)+1 as [Version] from reporting.Global_Audit where Object = @object and ObjectID = l.ObjectID) mv
insert into reporting.Global_FieldAudit (AuditID, FieldTypeID, FieldName, [Value], PreviousValue) select tt.ID as AuditID, coalesce(f.FieldTypeID, 0), ft.Name, f.[FormattedValue], pv.[Value] as PreviousValue from #Assets l inner join Asset a on a.Id = l.AssetID inner join @tbl tt on tt.Object = a.Object and tt.ObjectID = a.ObjectID inner join Field f on f.AssetID = l.AssetID inner join FieldType ft on ft.ID = f.FieldTypeID outer apply ( select top 1 ROW_NUMBER() OVER (PARTITION BY i_a.Object, i_a.ObjectID, iif(i_p.FieldTypeID = 0, i_p.FieldName, cast(i_p.FieldTypeID as nvarchar(100)) ) ORDER BY i_p.[AuditId] DESC) as RowNum, [Value] from reporting.Global_FieldAudit i_p inner join reporting.Global_Audit i_a on i_a.ID = i_p.AuditID and i_a.Object = @object and i_a.ObjectID = l.ObjectID and i_p.FieldTypeID = f.FieldTypeID order by RowNum asc ) pv where ((coalesce(pv.Value,'') = '' and coalesce(f.FormattedValue,'') != '') or (coalesce(f.Value,'') <> coalesce(pv.Value,'') COLLATE SQL_Latin1_General_CP1_CS_AS));
if (@object = 'Group') begin drop table if exists #fieldata; create table #fieldata (ObjectID int,SeqId int,FieldTypeID int,FieldName nvarchar(250),FieldValue NVARCHAR(4000),LookupValue NVARCHAR(4000)) insert into #fieldata select A.ObjectID,1 SeqId,0 as FieldTypeID, 'Name' as FieldName, G.Name as FieldValue, cast(null as nvarchar(max)) as LookupValue from #Assets A inner join [Group] G on A.ObjectID = G.ID union all select A.ObjectID,2 SeqId,0 as FieldTypeID, 'Description' as FieldName, G.Description as FieldValue, cast(null as nvarchar(max)) as LookupValue from #Assets A inner join [Group] G on A.ObjectID = G.ID union all select A.ObjectID,3 SeqId,0 as FieldTypeID, 'IsActiveDirectoryGroup' as FieldName, iif(g.IsActiveDirectoryGroup = 1, 'true', 'false') as FieldValue, cast(null as nvarchar(max)) as LookupValue from #Assets A inner join [Group] G on A.ObjectID = G.ID union all select A.ObjectID,4 SeqId,0 as FieldTypeID, 'PrimaryOwnerResourceID' as FieldName, cast(g.PrimaryOwnerResourceID as nvarchar(4000)) as FieldValue, cast(null as nvarchar(max)) as LookupValue from #Assets A inner join [Group] G on A.ObjectID = G.ID union all select A.ObjectID,5 SeqId,0 as FieldTypeID, 'SecondaryOwnerResourceID' as FieldName, cast(g.SecondaryOwnerResourceID as nvarchar(4000)) as FieldValue, cast(null as nvarchar(max)) as LookupValue from #Assets A inner join [Group] G on A.ObjectID = G.ID ;
insert into reporting.Global_FieldAudit (AuditID, FieldTypeID, FieldName, [Value], PreviousValue) select tt.ID as AuditID, coalesce(f.FieldTypeID, 0), f.FieldName, f.[FieldValue], pv.[Value] as PreviousValue from #Assets l inner join @tbl tt on tt.Object = @object and tt.ObjectID = l.ObjectID inner join #fieldata f on f.ObjectID = l.ObjectID outer apply ( select top 1 ROW_NUMBER() OVER (PARTITION BY i_a.Object, i_a.ObjectID, i_p.FieldName ORDER BY i_p.[AuditId] DESC) as RowNum, [Value] from reporting.Global_FieldAudit i_p inner join reporting.Global_Audit i_a on i_a.ID = i_p.AuditID and i_a.Object = @object and i_a.ObjectID = l.ObjectID and i_p.fieldName = f.fieldName and i_p.FieldTypeId = 0 order by RowNum asc ) pv where ((coalesce(pv.Value,'') = '' and coalesce(f.FieldValue,'') != '') or (coalesce(f.FieldValue,'') <> coalesce(pv.Value,'') COLLATE SQL_Latin1_General_CP1_CS_AS)) order by tt.ID,F.SeqId;
end end
